import { ChangeDetectionStrategy, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { DatepickerComponent } from '../datepicker/datepicker.component';
import { TimepickerComponent } from '../timepicker/timepicker.component';
import moment from 'moment'; // Correct default import

@Component({
  selector: 'datetime',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DatepickerComponent, TimepickerComponent],
  templateUrl: './datetime.component.html',
  styleUrl: './datetime.component.scss'
})
export class DatetimeComponent implements OnInit {

  @Input() date: any = moment().format('YYYY-MM-DD hh:mm A');
  @Input() type: string = 'T';
  @Output() dateChange = new EventEmitter<any>();
  @Input() disabled: boolean = false;
  dt: string;
  tm: string;
  constructor() {

  }


  ngOnInit(): void {
    if (isNaN(new Date(this.date).getTime())) {
      this.date = moment().format('YYYY-MM-DD hh:mm A');
    }
    this.dt = moment(new Date(this.date)).format('YYYY-MM-DD');
    this.tm = moment(new Date(this.date)).format('hh:mm A');
    this.bindDT();
  }

  OnDateChange(e: any, column: string) {
    this.dt = moment(new Date(e)).format('YYYY-MM-DD');
    this.bindDT();
  }

  OnTimeChange(e: any, column: string) {
    this.tm = e
    this.bindDT();
  }

  bindDT() {
    this.date = `${this.dt} ${this.tm}`;
    this.dateChange.emit(this.date);
  }

}
